def install_real_cap_hit_manifest(
    runs_root: Path, bundle_id: str, *, tamper: bool = False
) -> None:
    """Write the real campaign manifest + raw trace bytes for one cap-hit."""

    record = CAP_HIT_RECORDS[bundle_id]
    campaign_dir = runs_root / "campaign_manifests"
    raw_dir = campaign_dir / "raw"
    raw_dir.mkdir(parents=True, exist_ok=True)
    raw_bytes = base64.b64decode(record["raw_b64"])
    if tamper:
        raw_bytes += b'{"tampered":true}\n'
    (raw_dir / record["raw_name"]).write_bytes(raw_bytes)
    manifest = {
        "schema_version": "joulewise.campaign_provenance.v1",
        "session_id": record["session_id"],
        "analysis_manifest_id": None,
        "first_physical_run_id": record["first_physical_run_id"],
        "members": [
            {
                "run_id": bundle_id,
                "bundle_ids": [bundle_id],
                "execution": "invoked",
                "preceding_campaign_cooldown": record["cooldown"],
            }
        ],
        "cooldown_gates": [],
    }
    (campaign_dir / f"{record['session_id']}.json").write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )


def install_synthetic_recovered_manifest(
    runs_root: Path, bundle_ids: list[str], session_id: str = "synthetic-session"
) -> None:
    campaign_dir = runs_root / "campaign_manifests"
    raw_dir = campaign_dir / "raw"
    raw_dir.mkdir(parents=True, exist_ok=True)
    members = []
    for index, bundle_id in enumerate(bundle_ids):
        # The terminal cooldown record must corroborate the claimed
        # ``recovered`` disposition: ``release`` true == the gate released.
        trace = (
            json.dumps(
                {
                    "rolling_mean_power_w": 0.05,
                    "release": True,
                    "release_criteria_met_late": False,
                    "timestamp_s": float(index),
                }
            )
            + "\n"
        ).encode("utf-8")
        raw_name = f"{session_id}__cooldown_before_{bundle_id}.jsonl"
        (raw_dir / raw_name).write_bytes(trace)
        cooldown = (
            {
                "result": "first_run_exempt",
                "session_id": session_id,
                "following_run_id": bundle_id,
            }
            if index == 0
            else {
                "result": "recovered",
                "session_id": session_id,
                "following_run_id": bundle_id,
                "raw_artifact": {
                    "path": f"raw/{raw_name}",
                    "sha256": hashlib.sha256(trace).hexdigest(),
                    "records": 1,
                },
            }
        )
        members.append(
            {
                "run_id": bundle_id,
                "bundle_ids": [bundle_id],
                "execution": "invoked",
                **(
                    {
                        "role": "neg8_daily_reference_start",
                        "sentinel_position": "start",
                    }
                    if index == 0
                    else (
                        {
                            "role": "neg8_daily_reference_end",
                            "sentinel_position": "end",
                        }
                        if index == len(bundle_ids) - 1
                        else {}
                    )
                ),
                "preceding_campaign_cooldown": cooldown,
            }
        )
    (campaign_dir / f"{session_id}.json").write_text(
        json.dumps(
            {
                "schema_version": "joulewise.campaign_provenance.v1",
                "session_id": session_id,
                "analysis_manifest_id": None,
                "campaign_policy": {"sha256": TEST_POLICY_SHA256},
                "first_physical_run_id": bundle_ids[0],
                "members": members,
                "cooldown_gates": [],
            },
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )


def make_summary(
    value: float,
    *,
    metric: str = "gross_energy_j",
    reducer: str = "0.5.2",
    anchor_bound: float | None = 0.01,
    envelope_point: float | None = None,
    interpolation_bound: float = 0.0,
    precheck_eligible: bool = True,
    precheck_reasons: list[str] | None = None,
    idle_method: str = "duration_weighted_newey_west_bartlett_10s_iid_floor_v2",
) -> dict:
    """Minimal claim-shaped summary for extraction gates (synthetic inputs)."""

    is_phase = metric.startswith("phase_energy_j.")
    point = value if envelope_point is None else envelope_point
    summary: dict = {
        "status": "succeeded",
        "summary_provenance": {"reducer_version": reducer},
        "measurement_quality": {
            "cooldown_cap_hit": None,
            "idle_window_suspect": False,
            "telemetry_source": "mock",
        },
        LEGACY_THROUGHPUT_FIELD: 225.0,
        READER_THROUGHPUT_FIELD: 223.5,
        "energy_bound_terms_j": {
            "E_interpolation_joint_edge_bound_j": interpolation_bound,
            "E_drift_bound_j": 0.0,
        },
        "idle_mean_uncertainty": {
            "status": "estimated",
            "method": idle_method,
            "correlation_scope": "independent_run",
        },
        "energy_variance_terms_j2": {"E_idle_mean_j2": 1e-4},
    }
    precheck_row: dict = {
        "eligible": precheck_eligible,
        "reasons": list(precheck_reasons or []),
    }
    if is_phase:
        phase = metric.split(".", 1)[1]
        summary["phase_energy_j"] = {phase: value}
        summary["window_evidence_precheck"] = {
            "phase": {
                phase: {
                    **precheck_row,
                    "windows": [
                        {"interpolation_joint_edge_bound_j": interpolation_bound}
                    ],
                }
            }
        }
    else:
        summary[metric if metric != "idle_subtracted_energy_j" else "energy_request_j"] = value
        summary["window_evidence_precheck"] = {
            "gross_request": dict(precheck_row),
            "idle_subtracted_request": dict(precheck_row),
        }
        summary["gross_energy_j"] = summary.get("gross_energy_j", value)
        summary["energy_request_j"] = summary.get("energy_request_j", value)
    if anchor_bound is not None:
        pointer = (
            "/phase_energy_j/" + metric.split(".", 1)[1]
            if is_phase
            else "/" + ("energy_request_j" if metric == "idle_subtracted_energy_j" else metric)
        )
        summary["energy_anchor_shift_envelopes"] = {
            pointer: {
                "method": "common_trace_shift_plus_independent_edge_corners_v3",
                "anchor_bound_s": 0.05,
                "point_j": point,
                "lower_j": point - anchor_bound,
                "upper_j": point + anchor_bound,
                "max_abs_delta_j": anchor_bound,
            }
        }
        if not is_phase:
            summary["energy_bound_terms_j"]["E_clock_anchor_shift_bound_j"] = (
                anchor_bound
            )
    return summary


def write_bundle(runs_root: Path, bundle_id: str, summary: dict) -> None:
    bundle = runs_root / bundle_id
    bundle.mkdir(parents=True, exist_ok=True)
    (bundle / "summary_metrics.json").write_text(
        json.dumps(summary, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    # Synthetic claim-shaped members are current-era presentations unless a
    # regression explicitly overwrites this fixture with an absent or retired
    # capture shape.  B2 makes an omitted pipeline a distinct refusal rather
    # than a neutral legacy default.
    (bundle / "metadata.json").write_text(
        json.dumps(
            {"uncertainty_evidence": {"clock_anchor": {"method": CLOCK_METHOD_V3}}},
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )


class _PermissiveStrictValidatorMixin:
    """Neutralise the real D-030 strict validator for the hand-authored,
    summary-only synthetic bundles these gate tests build.

    Production runs the real ``validate_bundle`` (a summary-only bundle refuses
    with ``bundle_strict_invalid`` — see :class:`StrictValidationGateTests`);
    the gates under test here are the cooldown/precheck/anchor gates, so the
    synthetic bundles opt out of strict validation explicitly.
    """

    def setUp(self) -> None:  # noqa: D401 - unittest hook
        super().setUp()
        patcher = mock.patch(
            "joulewise.floor_extraction._default_strict_validator",
            lambda path, strict: [],
        )
        patcher.start()
        self.addCleanup(patcher.stop)
        whole_window_patcher = mock.patch(
            "joulewise.floor_extraction._whole_window_extraction_refusals",
            lambda runs_root, referenced_bundle_ids, **_kwargs: (),
        )
        whole_window_patcher.start()
        self.addCleanup(whole_window_patcher.stop)
        allowance_patcher = mock.patch(
            "joulewise.floor_extraction.whole_window_drift_allowances",
            lambda runs_root, referenced_bundle_ids, **_kwargs: (
                WholeWindowDriftAllowanceResult("legacy", {})
            ),
        )
        allowance_patcher.start()
        self.addCleanup(allowance_patcher.stop)


class D117MintConsumptionProfileTests(
    _PermissiveStrictValidatorMixin, unittest.TestCase
):
    FIXTURE_PATH = (
        Path(__file__).resolve().parent
        / "fixtures"
        / "d117_postcollection_trust"
        / "extraction_report.json"
    )

    @staticmethod
    def _allowance() -> dict:
        return {
            "claim_family": "gross_energy",
            "allowance_j": 0.05,
            "observed_trajectory_excursion_j": 0.05,
            "derived_repeatability_bound_j": 0.04,
            "provenance": {
                "bound_derivation_sha256": "a" * 64,
                "observed_component": "trajectory_excursion_max_j",
                "derived_component": "derived_repeatability_bound_j",
            },
            "whole_window_evaluation_basis_sha256": "b" * 64,
        }

    def _production_path_report(self, runs_root: Path) -> dict:
        bundle_ids = [f"golden-r{index:02d}" for index in range(1, 6)]
        install_synthetic_recovered_manifest(runs_root, bundle_ids)
        for index, bundle_id in enumerate(bundle_ids):
            write_bundle(
                runs_root,
                bundle_id,
                make_summary(40.0 + 0.1 * index, anchor_bound=0.01),
            )
        allowance = self._allowance()
        spec = {
            "schema_version": EXTRACTION_SPEC_SCHEMA_VERSION,
            "cells": [
                {
                    "cell_id": "D117-GOLDEN-ABS",
                    "kind": "absolute",
                    "metric": "gross_energy_j",
                    "window_class": "request",
                    "members": [
                        {"slot": bundle_id, "bundle_id": bundle_id}
                        for bundle_id in bundle_ids
                    ],
                }
            ],
        }
        with mock.patch(
            "joulewise.floor_extraction.whole_window_drift_allowances",
            return_value=WholeWindowDriftAllowanceResult(
                "allowances", {"gross_energy": allowance}
            ),
        ):
            report = extract_cells(runs_root, spec)
        report["runs_root"] = "<RUNS_ROOT>"
        return report

    def test_production_extractor_path_matches_checked_in_golden(self) -> None:
        expected = json.loads(self.FIXTURE_PATH.read_text(encoding="utf-8"))
        with tempfile.TemporaryDirectory() as tmp:
            actual = self._production_path_report(Path(tmp))
        self.assertEqual(validate_d117_mint_consumption_report(actual), [])
        self.assertEqual(actual, expected)

    def test_closed_profile_rejects_unknown_keys_at_every_level(self) -> None:
        fixture = json.loads(self.FIXTURE_PATH.read_text(encoding="utf-8"))
        mutations = (
            (fixture, "floor_mint_postcollection"),
            (fixture["cells"][0], "unknown_cell_field"),
            (fixture["cells"][0]["floor"], "unknown_floor_field"),
            (fixture["cells"][0]["members"][0], "unknown_member_field"),
        )
        for target, key in mutations:
            with self.subTest(key=key):
                attacked = json.loads(json.dumps(fixture))
                if target is fixture:
                    attacked[key] = {}
                elif target is fixture["cells"][0]:
                    attacked["cells"][0][key] = True
                elif target is fixture["cells"][0]["floor"]:
                    attacked["cells"][0]["floor"][key] = True
                else:
                    attacked["cells"][0]["members"][0][key] = True
                errors = validate_d117_mint_consumption_report(attacked)
                self.assertTrue(any(key in error for error in errors), errors)

    def test_closed_profile_rejects_injected_estimator_registration(self) -> None:
        report = json.loads(self.FIXTURE_PATH.read_text(encoding="utf-8"))
        report["cells"][0]["floor"]["estimator_registration"] = (
            two_shared_edge_common_mode_registration()
        )

        self.assertEqual(
            validate_d117_mint_consumption_report(report),
            [
                "extraction report: forbidden key 'estimator_registration' "
                "at extraction report.cells[0].floor.estimator_registration"
            ],
        )

    def test_registration_vocabulary_is_forbidden_at_every_nested_depth(
        self,
    ) -> None:
        registration = two_shared_edge_common_mode_registration()
        paths = (
            ("governance",),
            ("whole_window_drift_allowances", "gross_energy"),
            ("cells", 0, "members", 0, "operative_anchor_envelope"),
        )
        for path in paths:
            with self.subTest(path=path):
                report = json.loads(
                    self.FIXTURE_PATH.read_text(encoding="utf-8")
                )
                target = report
                for component in path:
                    target = target[component]
                target["estimator_registration"] = copy.deepcopy(registration)

                errors = validate_d117_mint_consumption_report(report)
                self.assertEqual(len(errors), 1, errors)
                self.assertIn("forbidden key 'estimator_registration'", errors[0])

    def test_pending_spec_registration_is_forbidden_in_admitted_report(
        self,
    ) -> None:
        # Post-D-133 the shipped specs carry no pending registration to
        # copy; the pending-candidate form is synthesized so the refusal
        # property stays exercised.
        report = json.loads(self.FIXTURE_PATH.read_text(encoding="utf-8"))
        pending = two_shared_edge_common_mode_registration()
        pending["status"] = "candidate_pending_floor_commonmode_01"
        report["governance"]["estimator_registration"] = pending

        errors = validate_d117_mint_consumption_report(report)
        self.assertEqual(len(errors), 1, errors)
        self.assertIn("forbidden key 'estimator_registration'", errors[0])

    def test_unicode_escaped_nested_registration_key_is_forbidden(self) -> None:
        report = json.loads(self.FIXTURE_PATH.read_text(encoding="utf-8"))
        escaped = json.loads(
            r'{"estimator_registr\u0061tion":{"status":"forged"}}'
        )
        report["whole_window_drift_allowances"]["gross_energy"].update(escaped)

        errors = validate_d117_mint_consumption_report(report)
        self.assertEqual(len(errors), 1, errors)
        self.assertIn("forbidden key 'estimator_registration'", errors[0])

    def test_bundle_json_admission_refuses_duplicate_keys_at_every_depth(
        self,
    ) -> None:
        for label, raw in (
            ("top", b'{"status":"forged","status":"succeeded"}'),
            ("nested", b'{"floor":{"value":1,"value":2}}'),
            ("nonfinite", b'{"floor":NaN}'),
            ("overflow", b'{"floor":{"value":1e999}}'),
            (
                "registration",
                b'{"nested":[{"estimator_registration":{}}]}',
            ),
        ):
            with self.subTest(label=label), self.assertRaises(
                FloorExtractionError
            ):
                _strict_admission_json_value(raw, "bundle evidence")

    def test_duplicate_summary_bytes_fail_closed_as_unreadable(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            bundle = Path(tmp) / "bundle"
            bundle.mkdir()
            raw = b'{"gross_energy_j":999,"gross_energy_j":1}\n'
            (bundle / "summary_metrics.json").write_bytes(raw)

            value, digest, refusal = _read_summary(bundle)

        self.assertIsNone(value)
        self.assertEqual(digest, hashlib.sha256(raw).hexdigest())
        self.assertEqual(refusal, "summary_unreadable")

    def test_overflowed_summary_number_fails_closed_as_unreadable(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            bundle = Path(tmp) / "bundle"
            bundle.mkdir()
            raw = b'{"phase_energy_j":{"decode":1e999}}\n'
            (bundle / "summary_metrics.json").write_bytes(raw)

            value, digest, refusal = _read_summary(bundle)

        self.assertIsNone(value)
        self.assertEqual(digest, hashlib.sha256(raw).hexdigest())
        self.assertEqual(refusal, "summary_unreadable")

    def test_nested_registration_summary_fails_closed_as_unreadable(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            bundle = Path(tmp) / "bundle"
            bundle.mkdir()
            raw = b'{"nested":[{"estimator_registration":{}}]}\n'
            (bundle / "summary_metrics.json").write_bytes(raw)

            value, digest, refusal = _read_summary(bundle)

        self.assertIsNone(value)
        self.assertEqual(digest, hashlib.sha256(raw).hexdigest())
        self.assertEqual(refusal, "summary_unreadable")


class AnalysisAdmissionStrictParsingTests(unittest.TestCase):
    def test_analysis_manifest_entry_refuses_duplicate_and_deleted_vocabulary(
        self,
    ) -> None:
        cases = (
            (
                "duplicate",
                b'{"schema_version":"forged","schema_version":"valid"}\n',
                "duplicate JSON key",
            ),
            (
                "registration",
                b'{"nested":[{"estimator_registration":{}}]}\n',
                "forbidden key 'estimator_registration'",
            ),
            (
                "overflow",
                b'{"nested":{"value":1e999}}\n',
                "non-finite JSON number '1e999'",
            ),
        )
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "analysis-manifest.json"
            for label, raw, message in cases:
                with self.subTest(label=label):
                    path.write_bytes(raw)
                    with self.assertRaisesRegex(AnalysisInputError, message):
                        load_analysis_manifest(path)

    def test_analysis_jsonl_entry_refuses_duplicate_and_deleted_vocabulary(
        self,
    ) -> None:
        for label, raw, message in (
            ("duplicate", b'{"x":1,"x":2}\n', "duplicate JSON key"),
            (
                "registration",
                b'{"rows":[{"estimator_registration":{}}]}\n',
                "forbidden key 'estimator_registration'",
            ),
            (
                "overflow",
                b'{"rows":[{"value":1e999}]}\n',
                "non-finite JSON number '1e999'",
            ),
        ):
            with self.subTest(label=label), self.assertRaisesRegex(
                AnalysisInputError, message
            ):
                _strict_jsonl_admission_bytes(raw, "analysis JSONL evidence")

    def test_registry_entry_refuses_duplicate_and_deleted_vocabulary(
        self,
    ) -> None:
        cases = (
            ("duplicate", b'{"safe":1,"safe":2}\n', "duplicate JSON key"),
            (
                "registration",
                b'{"nested":{"estimator_registration":{}}}\n',
                "forbidden key 'estimator_registration'",
            ),
            (
                "overflow",
                b'{"nested":{"value":1e999}}\n',
                "non-finite JSON number '1e999'",
            ),
        )
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            manifest_path = root / "manifest.json"
            manifest_path.write_text("{}\n", encoding="utf-8")
            registry_path = root / "registry.json"
            for label, raw, message in cases:
                with self.subTest(label=label):
                    registry_path.write_bytes(raw)
                    with self.assertRaisesRegex(AnalysisManifestError, message):
                        load_and_validate_analysis_manifest_v2(
                            manifest_path, registry_path
                        )

    def test_nested_overflow_in_floor_artifact_bytes_is_refused_prevalidation(
        self,
    ) -> None:
        with self.assertRaisesRegex(
            AnalysisInputError,
            "non-finite JSON number '1e999'",
        ):
            authenticate_floor_artifact_bytes(
                b'{"nested":{"artifact_number":1e999}}'
            )


class RealCapHitJoinTests(unittest.TestCase):
    def test_embedded_fixtures_are_the_four_audited_records(self) -> None:
        self.assertEqual(set(CAP_HIT_RECORDS), set(AUDIT_CAP_HIT_TABLE))
        for bundle_id, (waited, decision, upper) in AUDIT_CAP_HIT_TABLE.items():
            record = CAP_HIT_RECORDS[bundle_id]
            cooldown = record["cooldown"]
            self.assertEqual(cooldown["result"], "cap_hit")
            self.assertEqual(cooldown["waited_s"], waited)
            self.assertEqual(cooldown["decision_rolling_mean_power_w"], decision)
            self.assertEqual(cooldown["effective_upper_w"], upper)
            raw_bytes = base64.b64decode(record["raw_b64"])
            self.assertEqual(
                hashlib.sha256(raw_bytes).hexdigest(),
                cooldown["raw_artifact"]["sha256"],
                f"embedded raw trace for {bundle_id} is not the sealed artifact",
            )

    def test_all_four_real_records_join_as_verified_cap_hits(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            runs_root = Path(tmp)
            for bundle_id in AUDIT_CAP_HIT_TABLE:
                install_real_cap_hit_manifest(runs_root, bundle_id)
            joined = campaign_cooldown_evidence(runs_root)
            for bundle_id in AUDIT_CAP_HIT_TABLE:
                row = joined[bundle_id]
                self.assertEqual(row["result"], "cap_hit")
                self.assertTrue(row["verified"])

    def test_tampered_raw_trace_never_verifies(self) -> None:
        bundle_id = "p2015-df-rq-long-prompt-abs-r03"
        with tempfile.TemporaryDirectory() as tmp:
            runs_root = Path(tmp)
            install_real_cap_hit_manifest(runs_root, bundle_id, tamper=True)
            joined = campaign_cooldown_evidence(runs_root)
            self.assertFalse(joined[bundle_id]["verified"])

    def test_relabelled_result_field_never_verifies(self) -> None:
        # The mutable manifest ``result`` is edited from the true ``cap_hit``
        # (raw terminal record has release=False) to a clean ``recovered``,
        # keeping the raw bytes and their sha256 pin intact.  Hash verification
        # of the bytes alone would trust the relabel; corroborating the
        # disposition against the terminal record must refuse it.
        bundle_id = "p2015-df-rq-long-prompt-abs-r03"
        with tempfile.TemporaryDirectory() as tmp:
            runs_root = Path(tmp)
            install_real_cap_hit_manifest(runs_root, bundle_id)
            record = CAP_HIT_RECORDS[bundle_id]
            manifest_path = (
                runs_root / "campaign_manifests" / f"{record['session_id']}.json"
            )
            manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
            manifest["members"][0]["preceding_campaign_cooldown"]["result"] = (
                "recovered"
            )
            manifest_path.write_text(
                json.dumps(manifest, indent=2, sort_keys=True) + "\n",
                encoding="utf-8",
            )
            joined = campaign_cooldown_evidence(runs_root)
            self.assertEqual(joined[bundle_id]["result"], "recovered")
            self.assertFalse(joined[bundle_id]["verified"])

    def test_ambiguous_duplicate_records_never_verify(self) -> None:
        bundle_id = "p2015-df-ph-short-prefill-abs-r04"
        record = CAP_HIT_RECORDS[bundle_id]
        with tempfile.TemporaryDirectory() as tmp:
            runs_root = Path(tmp)
            install_real_cap_hit_manifest(runs_root, bundle_id)
            # A second manifest claims the same bundle recovered cleanly.
            conflicting = {
                "schema_version": "joulewise.campaign_provenance.v1",
                "session_id": record["session_id"],
                "analysis_manifest_id": None,
                "first_physical_run_id": bundle_id,
                "members": [
                    {
                        "run_id": bundle_id,
                        "bundle_ids": [bundle_id],
                        "execution": "invoked",
                        "preceding_campaign_cooldown": {
                            "result": "first_run_exempt",
                            "session_id": record["session_id"],
                            "following_run_id": bundle_id,
                        },
                    }
                ],
                "cooldown_gates": [],
            }
            (runs_root / "campaign_manifests" / "conflict.json").write_text(
                json.dumps(conflicting, indent=2, sort_keys=True) + "\n",
                encoding="utf-8",
            )
            joined = campaign_cooldown_evidence(runs_root)
            self.assertFalse(joined[bundle_id]["verified"])
            self.assertEqual(joined[bundle_id]["result"], "unknown")

    def test_byte_identical_duplicate_member_records_never_verify(self) -> None:
        # F9 defect shape: canonical-set collapse used to turn two identical
        # member occurrences into one apparently unambiguous verified row.
        bundle_id = "p2015-df-rq-long-prompt-abs-r03"
        record = CAP_HIT_RECORDS[bundle_id]
        with tempfile.TemporaryDirectory() as tmp:
            runs_root = Path(tmp)
            install_real_cap_hit_manifest(runs_root, bundle_id)
            manifest_path = (
                runs_root / "campaign_manifests" / f"{record['session_id']}.json"
            )
            manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
            manifest["members"].append(
                json.loads(json.dumps(manifest["members"][0]))
            )
            manifest_path.write_text(
                json.dumps(manifest, indent=2, sort_keys=True) + "\n",
                encoding="utf-8",
            )
            joined = campaign_cooldown_evidence(runs_root)
        self.assertEqual(joined[bundle_id]["result"], "unknown")
        self.assertFalse(joined[bundle_id]["verified"])


