    def test_floor_refuses_missing_and_explicitly_unenforced_cpu_admission(self) -> None:
        # W4 defect shape: both bundles had finite metrics/envelopes and clean
        # cooldown rows, but one had no CPU record and the other explicitly
        # bypassed it.  Pre-fix floor extraction admitted both.
        with tempfile.TemporaryDirectory() as tmp:
            runs_root = Path(tmp)
            for bundle_id, value in (("missing", 40.0), ("unenforced", 40.1)):
                write_bundle(runs_root, bundle_id, self._powermetrics_summary(value))
            missing_metadata: dict = {}
            self._bind_powermetrics_config(
                runs_root / "missing", "missing", missing_metadata
            )
            (runs_root / "missing" / "metadata.json").write_text(
                json.dumps(missing_metadata) + "\n",
                encoding="utf-8",
            )
            unenforced_metadata = {
                "environment_admission": {
                    "decision": "admitted",
                    "attempts": [
                        {
                            "attempt": 1,
                            "admitted": True,
                            "cpu_admission_enforced": False,
                            "cpu_admission": {"admitted": True},
                        }
                    ],
                }
            }
            self._bind_powermetrics_config(
                runs_root / "unenforced",
                "unenforced",
                unenforced_metadata,
            )
            (runs_root / "unenforced" / "metadata.json").write_text(
                json.dumps(unenforced_metadata) + "\n"
            )
            cooldowns = {
                bundle_id: {"result": "recovered", "verified": True}
                for bundle_id in ("missing", "unenforced")
            }
            report = extract_absolute_cell(
                cell_id="cpu-barrier",
                metric="gross_energy_j",
                window_class="request",
                members=[
                    {"slot": "a", "bundle_id": "missing"},
                    {"slot": "b", "bundle_id": "unenforced"},
                ],
                runs_root=runs_root,
                cooldowns=cooldowns,
                strict_validator=lambda path, strict: [],
            )
        self.assertIn("environment_admission_missing", report.refusal_reasons)
        self.assertIn("cpu_admission_unenforced", report.refusal_reasons)

