class ComparativeCellExtractionTests(_PermissiveStrictValidatorMixin, unittest.TestCase):
    def _build_blocks(self, runs_root: Path) -> list[dict]:
        cap_hit_id = "p2015-df-cmp-abba-su-b01-b1"
        install_real_cap_hit_manifest(runs_root, cap_hit_id)
        blocks = []
        synthetic_ids: list[str] = []
        base = {"A1": 32.4, "B1": 32.2, "B2": 32.3, "A2": 32.5}
        for block_index in (1, 2, 3):
            block_id = f"b{block_index:02d}"
            members = {}
            for position in ("A1", "B1", "B2", "A2"):
                if block_index == 1 and position == "B1":
                    bundle_id = cap_hit_id
                else:
                    bundle_id = f"su-{block_id}-{position.lower()}"
                    synthetic_ids.append(bundle_id)
                members[position] = bundle_id
                write_bundle(
                    runs_root,
                    bundle_id,
                    make_summary(base[position] + 0.01 * block_index),
                )
            blocks.append({"block_id": block_id, "members": members})
        install_synthetic_recovered_manifest(runs_root, synthetic_ids)
        return blocks

    def test_cap_hit_excludes_its_whole_block_same_slot(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            runs_root = Path(tmp)
            blocks = self._build_blocks(runs_root)
            report = extract_comparative_cell(
                cell_id="DF-CMP-ABBA-SU",
                metric="gross_energy_j",
                window_class="request",
                blocks=blocks,
                runs_root=runs_root,
                cooldowns=campaign_cooldown_evidence(runs_root),
            )
        self.assertTrue(report.extractable)
        self.assertIn(
            "admissible_set_uncertainty_dominates_point_floor",
            report.refusal_reasons,
        )
        self.assertEqual(report.excluded_slots, ("b01",))
        self.assertEqual(report.n_planned, 3)
        self.assertEqual(report.n_admitted, 2)
        excluded_members = [m for m in report.members if m.excluded]
        # ALL FOUR members of the cap-hit block are out, not just the cap-hit.
        self.assertEqual(len(excluded_members), 4)
        self.assertEqual({m.block_id for m in excluded_members}, {"b01"})
        assert report.floor is not None
        self.assertEqual(report.floor.n, 2)
        # n_blocks=2 < 5: smoke-only, the guarded floor MUST be withheld.
        self.assertIsNone(report.floor.guarded_floor_j)
        self.assertIsNone(report.floor.guard_factor)
        assert report.point_floor_diagnostic is not None
        row = report.as_row()
        self.assertEqual(
            row["floor"]["admissible_half_widths_j"],
            [0.02, 0.02],
        )
        self.assertEqual(
            row["floor"]["corner_widened_unguarded_floor_j"],
            report.floor.corner_widened_unguarded_floor_j,
        )
        self.assertEqual(
            row["floor"]["corner_widened_guarded_floor_j"],
            report.floor.corner_widened_guarded_floor_j,
        )
        self.assertEqual(row["floor_source"], ATTRIBUTION_FLOOR_SOURCE)
        self.assertEqual(row["floor_limit_class"], ATTRIBUTION_LIMIT_CLASS)
        self.assertEqual(
            row["point_floor_diagnostic"],
            {
                "label": "repeatability_diagnostic",
                "published_claim_floor": False,
                "unguarded_floor_j": report.point_floor_diagnostic.unguarded_floor_j,
                "guard_factor": None,
                "guarded_floor_j": None,
            },
        )
        self.assertEqual(
            row["single_count_discipline"],
            attribution_single_count_discipline(),
        )

